function repeatSeq(fn, interval, Nt, onComplete)
{
    let t = 0;
    function run()
    {
        if (t < Nt)
        {
            fn(t);
            t++;
            setTimeout(run, interval);
        }
        else
        {
            onComplete();
        }
    }
    run();
}
function animationSeqID3(t){
    var e = document.getElementById("contentsID602");
    var x1 = 350;
    var y1 = 780-390;
    var x2 = 350+198*t/499;
    var y2 = 780-390;
    e.setAttribute("style","visibility: visible; stroke-width: 4px; stroke-dasharray: 4,4; stroke: #ff69b4;");
    e.setAttribute("x1", x1);
    e.setAttribute("y1", y1);
    e.setAttribute("x2", x2);
    e.setAttribute("y2", y2);
}
function animationSeqID4(t){
    var e = document.getElementById("contentsID603");
    var x1 = 350+198*Math.cos(3.141592653589793*0/180);
    var y1 = 780-(390+198*Math.sin(3.141592653589793*0/180));
    var x2 = 350+198*Math.cos(3.141592653589793*360*t/99/180-0.0001);
    var y2 = 780-(390+198*Math.sin(3.141592653589793*360*t/99/180-0.0001));
    var a1 = 0;
    var a2 = 360*t/99;
    var radiusX = 198;
    var radiusY = 198;
    var da = a2 - a1;
    if(da < 0.0) {da = a2 + 360 - a1;}
    var largerOrSmaller = 0;
    if(da > 180.0) {largerOrSmaller = 1;}
    d = "M " + x1 + " " + y1 + " A " + radiusX + " " + radiusY + " 0 " + largerOrSmaller + " 0 " + x2 + " " + y2 ;
    e.setAttribute("style","visibility: visible; stroke-width: 6px; stroke: #006400; fill: none;");
    e.setAttribute("d", d);
}
function repeatSeq(fn, interval, Nt, onComplete)
{
    let t = 0;
    function run()
    {
        if (t < Nt)
        {
            fn(t);
            t++;
            setTimeout(run, interval);
        }
        else
        {
            onComplete();
        }
    }
    run();
}
